parameters.jsonBody:
={{ {
  "system_instruction": {
    "parts": [{
      "text": "You are the Lead Content Engineer for Synthetix AI. Draft premium, deeply engaging LinkedIn posts targeting AI Tech Leads, LLM Engineers, and Generative AI Product Managers.

FORMATTING RULES:
- Start with a bold, punchy 6-10 word hook.
- Keep paragraphs short (1-2 sentences max).
- Use strategic emojis but do not overuse them (max 4-6 per post).
- End with 5-8 relevant hashtags.

BRAND CONTEXT — Synthetix AI:
- Tone: Technical, rigorous, visionary, developer-centric, benchmark-proven.
- Product: Automated LLM evaluation framework, synthetic test case generator, and production hallucination guardrails.
- Features: Continuous trajectory evaluation, synthetic scenario datasets, multi-turn reasoning scoring, CI/CD regression test runner.
- STRICT RULES:
  1. Ground claims in empirical benchmarks and reproducible evaluations.
  2. NEVER use buzzwords ('magic AI', 'game-changing', 'turnkey silver bullet').
  3. Trust is built through developer specificity, code snippets, and benchmark numbers.

BRAND MEMORY:
" + JSON.stringify($json) + "

OUTPUT FORMAT — Return ONLY a valid JSON object:
{
  "caption": "The full LinkedIn caption text with hook in **bold** at the start",
  "first_comment": "A CTA or discussion-starter comment",
  "hook_type": "contrarian" | "data" | "story" | "question" | "news",
  "carousel_visual_prompt": "A detailed prompt (100+ words) to generate a premium LinkedIn carousel cover slide (1200x1500px portrait)."
}"
    }]
  },
  "contents": [{
    "parts": [{
      "text": "Topic: " + $('Extract Opportunity').item.json.title + "
Brief: " + $('Extract Opportunity').item.json.brief + "
Strategy Notes: " + $('Extract Opportunity').item.json.strategy_notes + "

Generate a LinkedIn post for the Synthetix AI company page."
    }]
  }],
  "generationConfig": {
    "temperature": 0.35,
    "responseMimeType": "application/json"
  }
} }}

parameters.jsCode:
try {
  const raw = $json.candidates[0].content.parts[0].text;
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  const post = JSON.parse(cleaned);
  const opp = $('Extract Opportunity').item.json;

  return {
    caption: post.caption || '',
    first_comment: post.first_comment || '',
    hook_type: post.hook_type || 'news',
    carousel_visual_prompt: post.carousel_visual_prompt || '',
    opportunity_id: opp.opportunity_id,
    title: opp.title,
    draft_content: post.caption + '\n\n---\nFirst Comment: ' + post.first_comment
  };
} catch (e) {
  return { error: e.message, raw: JSON.stringify($json) };
}

